        scene=scene with{Meshes=scene.Meshes.Select(m=>m with{Vertices=m.Vertices.Select(v=>{int j=(int)v.Joints.X;Matrix4x4.Invert(old.World[j],out var inverse);var p=Vector3.Transform(v.Position,inverse);if(j is 10 or 13)p.Y*=.55f;if(j is 11 or 14)p.Y*=1.2f;if(j is 4 or 7)p.X*=1.55f;return v with{Position=Vector3.Transform(p,bind.World[j])};}).ToArray()}).ToArray()};return source with{Id=Guid.NewGuid(),Scene=scene,Clips=[],Contacts=[]};
