        var climbResult=RetargetService.Bake(original with{Clips=[climb]},climb,a,target,b,ground:new());check(climbResult.Value is not null,"Below-ledge hang and later above-ground get-up bake without treating the top plane as an infinite floor: "+string.Join("; ",climbResult.Diagnostics.Where(d=>d.Error).Select(d=>d.Message)));var cv=climbResult.Value!;
        check(cv.Grounding!.Phases.Any(p=>p.Mode==SupportSurfaceMode.Edge)&&cv.Grounding.Phases.Any(p=>p.Mode==SupportSurfaceMode.Ground)&&cv.Contacts.Where(c=>c.Contains(2)).SelectMany(c=>c.Pins).All(p=>p.EdgeSupport&&p.Clearance is null),"Ledge phases preserve hand anchors while suspending whole-body floor constraints below the edge");
        var below=AnimationService.Evaluate(target.Scene,cv.Clip,2.375);var above=AnimationService.Evaluate(target.Scene,cv.Clip,22.375);check(target.Scene.Meshes.SelectMany(m=>m.Vertices).Min(v=>AnimationService.Skin(v,below).Y)<cv.Grounding.TargetFloor-.5f&&target.Scene.Meshes.SelectMany(m=>m.Vertices).Min(v=>AnimationService.Skin(v,above).Y)>=cv.Grounding.TargetFloor-.001f,"Actual target geometry remains intentionally below the ledge early and clears the ground after getting up");
        var free=SurfaceContacts.Detect(donor,crouch,a,new(){SurfaceMode=SupportSurfaceMode.Free});check(free.Contacts.Length==0&&free.Phases.All(p=>p.Mode==SupportSurfaceMode.Free),"Actor-controlled airborne/free context disables guessed model-space ground contacts explicitly");
        var sunken=original with{Scene=original.Scene with{Meshes=original.Scene.Meshes.Select(m=>m with{Vertices=m.Vertices.Select(v=>(int)v.Joints.X is 12 or 15?v with{Position=v.Position-new Vector3(0,.2f,0)}:v).ToArray()}).ToArray()}};
        var standing=new AnimationClip(Guid.NewGuid(),"Penetrating soles are not a ledge",12,new(60),false,[]);
        check(SurfaceContacts.Detect(sunken with{Clips=[standing]},standing,a,new()).Phases.All(p=>p.Mode!=SupportSurfaceMode.Edge),"Below-floor extremity vertices do not misclassify an otherwise above-ground torso as a hanging ledge phase");
        check(checksum==AnimationControls.DeformChecksum(target.Scene)&&before==JsonSerializer.Serialize(donor,ProjectStore.Json),"Whole-body surface analysis/retargeting leave original source data and target bones/binds/weights unchanged");
        var explicitPin=new ContactFrame(Guid.NewGuid(),crouch.Id,0,a.SkeletonFingerprint,[ContactSolver.Capture(original.Scene,AnimationService.Evaluate(original.Scene,crouch,0),a,"Foot.L")]){EndFrame=3};var manual=SurfaceContacts.Detect(donor with{Contacts=[explicitPin]},crouch,a,new());check(manual.Contacts.All(c=>c.Pins.All(p=>p.Role!="Foot.L")),"Authored contact/release policy takes precedence over automatic detection for that region");
        var broken=bake.Contacts[0].Pins[0] with{SurfacePoints=[new(Vector3.Zero,new(999,0,0,0),new(1,0,0,0))]};check(ContactSolver.Solve(target.Scene,AnimationService.Evaluate(target.Scene,null,0),b,new Dictionary<int,Transform>(),[broken],true).Value is null,"Malformed cached skin constraints fail precisely before evaluation");
    }
    static AnimationClip AlignFloor(Scene scene,AnimationClip clip,float floor)
    {
        var p=AnimationService.Evaluate(scene,clip,0);float min=scene.Meshes.SelectMany(m=>m.Vertices).Min(v=>AnimationService.Skin(v,p).Y);var root=clip.Sample(scene.Bones[0],0);return clip with{Tracks=clip.Tracks.Where(t=>t.Bone!=scene.Bones[0].Name).Append(new BoneTrack(scene.Bones[0].Name,(root with{Translation=root.Translation+new Vector3(0,floor-min,0)}).Channels().Select(v=>(Curve?)new Curve([new(0,v)])).ToArray())).ToArray()};
    }
    static async Task BodyCase(FighterProject donor,FighterProject target,ControlRigSetup a,ControlRigSetup b,AnimationClip clip,string expected,string directory,Action<bool,string> check)
    {
        donor=donor with{Clips=[clip]};var result=RetargetService.Bake(donor,clip,a,target,b,ground:new());check(result.Value is not null,$"{clip.Name} retarget succeeds with whole-body surface constraints: "+string.Join("; ",result.Diagnostics.Select(d=>d.Message)));var value=result.Value!;
        var pins=value.Contacts.SelectMany(c=>c.Pins).ToArray();check(pins.Any(p=>p.Role.StartsWith(expected,StringComparison.Ordinal)),$"{clip.Name} detects {expected} geometry support without source annotations");
        var pose=AnimationService.Evaluate(target.Scene,value.Clip,4.375);check(pins.All(p=>ContactGeometry.Residual(p,pose).Length()<.001f&&ContactGeometry.Penetration(p,pose)<.001f),$"{clip.Name} keeps target skinned support regions at the ground across unequal proportions");
        check(target.Scene.Meshes.SelectMany(m=>m.Vertices).Min(v=>AnimationService.Skin(v,pose).Y)>=value.Grounding!.TargetFloor-.001f,$"{clip.Name} independently checks every target mesh vertex for floor penetration");
        string path=Path.Combine(directory,clip.Name.Replace(' ','-')+".fighterport");await ProjectStore.SaveAsync(RetargetService.Apply(target with{ControlRigs=[b]},value),path);var reopened=await ProjectStore.LoadAsync(path);check(reopened.Contacts.SelectMany(c=>c.Pins).All(p=>p.SurfacePoints.Length>0)&&reopened.LibrarySources[0].Analysis?.Ground.Contacts.Length>0,$"{clip.Name} weighted support/source evidence survives project save/reopen separately from original annotations");
        check(reopened.LibrarySources[0].Analysis?.Ground.BodySupportedThroughout==value.Source.Analysis?.Ground.BodySupportedThroughout&&reopened.LibrarySources[0].Analysis!.Ground.BodySupportPhases.SequenceEqual(value.Source.Analysis!.Ground.BodySupportPhases)&&reopened.LibrarySources[0].Analysis!.Ground.BodySupportedAtClosing==value.Source.Analysis!.Ground.BodySupportedAtClosing&&reopened.Contacts.SelectMany(c=>c.Pins).Select(p=>p.Clearance?.SupportPoints.Length??0).SequenceEqual(value.Contacts.SelectMany(c=>c.Pins).Select(p=>p.Clearance?.SupportPoints.Length??0)),$"{clip.Name} saves source body phases/closing context and target support calibration without replacing either rig");
    }
}
